    "stage4.ui.4e2fd9a9ddeb": "Menunggu koreksi",
    "stage4.ui.4e99ffd2ae06": "Karena ini pengembalian unit terakhir, seluruh jaminan fisik wajib dikonfirmasi sudah dikembalikan.",
    "stage4.ui.519c5796eec3": "Transfer Aset Antar-Cabang",
    "stage4.ui.51a1a65ee7cb": "Customer360 menyimpan data identitas; centang ini hanya ketika dokumen/barang fisiknya benar-benar berada pada petugas.",
    "stage4.ui.51d7d22341f4": "Deposit wajib",
    "stage4.ui.520abfec3a84": "Kondisi fisik, tempat penyimpanan, atau catatan lain",
    "stage4.ui.520de3bd0bd8": "Alasan pembukaan kembali",
    "stage4.ui.5265a07710c5": "Item yang diperpanjang",
    "stage4.ui.5301648dcf6b": "Edit",
    "stage4.ui.53dcc7737065": "Faktur, Nota & Perjanjian",
    "stage4.ui.53eb1a623ade": "Metode pembayaran",
    "stage4.ui.544f0ae5c151": "Denda keterlambatan dihitung otomatis oleh server dari jatuh tempo efektif setiap item. Nilai di bawah adalah pratinjau dan akan dihitung ulang saat disimpan.",
    "stage4.ui.54c24ed70f3b": "Pantau rental aktif, keterlambatan, sisa tagihan, pengembalian sebagian, dan transaksi antar-cabang dalam satu layar.",
    "stage4.ui.54fdf9054ea7": "Nomor identitas",
