    "stage4.ui.575164e1b40d": "Member aktif: diskon 10% otomatis. Promo diskon memakai nilai terbaik kecuali promo mengizinkan stacking.",
    "stage4.ui.580126f82ca4": "Cari rental, pelanggan, booking asal, produk, kode aset, atau serial number.",
